(function () {
  if (!/(^|\.)youtube\.com$/.test(location.hostname)) return;
  if (window.__youpupAds) return;
  window.__youpupAds = true;

  // 1. Strip ad slots from player data wherever it enters the page.
  const AD_KEYS = ['adPlacements', 'adSlots', 'playerAds', 'adBreakHeartbeatParams', 'adBreakParams'];
  const prune = (o) => {
    if (!o || typeof o !== 'object') return o;
    for (const k of AD_KEYS) if (k in o) delete o[k];
    if (o.playerResponse) prune(o.playerResponse);
    if (Array.isArray(o)) o.forEach((x) => { if (x && typeof x === 'object' && x.playerResponse) prune(x.playerResponse); });
    return o;
  };
  const looksLikePlayerData = (o) => o && typeof o === 'object' &&
    (AD_KEYS.some((k) => k in o) || 'playerResponse' in o || Array.isArray(o));

  const origParse = JSON.parse;
  JSON.parse = function () {
    const result = origParse.apply(this, arguments);
    try { if (looksLikePlayerData(result)) prune(result); } catch (e) {}
    return result;
  };

  const origJson = Response.prototype.json;
  Response.prototype.json = function () {
    return origJson.call(this).then((r) => { try { prune(r); } catch (e) {} return r; });
  };

  for (const name of ['ytInitialPlayerResponse', 'ytInitialData']) {
    let value;
    try {
      Object.defineProperty(window, name, {
        configurable: true,
        get: () => value,
        set: (v) => { value = prune(v); }
      });
    } catch (e) {}
  }

  // 2. Anything that slips through: mute, jump to the end and press Skip.
  let mutedByUs = false;
  let spedUpByUs = false;
  const SKIP = '.ytp-ad-skip-button, .ytp-ad-skip-button-modern, .ytp-skip-ad-button, ' +
               '.ytp-ad-skip-button-slot button, .ytm-ad-skip-button, button[class*="skip-ad"], button[class*="ad-skip"]';
  const tick = (video) => {
    const player = video.closest('.html5-video-player');
    if (!player) return;
    const adShowing = player.classList.contains('ad-showing') || player.classList.contains('ad-interrupting');
    if (adShowing) {
      player.querySelectorAll(SKIP).forEach((b) => { try { b.click(); } catch (e) {} });
      if (!video.muted) { video.muted = true; mutedByUs = true; }
      if (video.playbackRate !== 16) { video.playbackRate = 16; spedUpByUs = true; }
      if (isFinite(video.duration) && video.duration > 0 && video.currentTime < video.duration - 0.1) {
        video.currentTime = video.duration - 0.05;
      }
    } else {
      if (mutedByUs) { video.muted = false; mutedByUs = false; }
      if (spedUpByUs) { video.playbackRate = 1; spedUpByUs = false; }
    }
  };
  // Event-driven: timeupdate fires a few times a second only while a video is actually playing.
  for (const type of ['playing', 'loadedmetadata', 'timeupdate']) {
    document.addEventListener(type, (e) => { if (e.target.tagName === 'VIDEO') tick(e.target); }, true);
  }
})();

