(function () {
  if (!/(^|\.)youtube\.com$/.test(location.hostname)) return;
  if (window.__youpup) return;

  const prefs = window.__youpupPrefs || { backgroundPlay: true };

  // YouTube pauses video when the page reports itself hidden. Always report visible
  // so audio keeps going with the screen locked or the app in the background.
  if (prefs.backgroundPlay) try {
    const def = (name, value) => Object.defineProperty(Document.prototype, name, { get: () => value, configurable: true });
    def('hidden', false);
    def('webkitHidden', false);
    def('visibilityState', 'visible');
    def('webkitVisibilityState', 'visible');
  } catch (e) {}
  const swallow = (e) => e.stopImmediatePropagation();
  if (prefs.backgroundPlay) {
    document.addEventListener('visibilitychange', swallow, true);
    document.addEventListener('webkitvisibilitychange', swallow, true);
  }

  const post = (msg) => {
    // Handed to the isolated bridge world; pages never see window.webkit.
    document.dispatchEvent(new CustomEvent('__youpup', { detail: JSON.stringify(msg) }));
  };

  const unlock = (v) => {
    if (!v) return;
    v.removeAttribute('disablepictureinpicture');
    try { v.disablePictureInPicture = false; } catch (e) {}
    v.setAttribute('playsinline', '');
  };

  const isPiP = (v) => !!v && (v.webkitPresentationMode === 'picture-in-picture' || document.pictureInPictureElement === v);

  const api = {
    wasPlaying: false,
    video() {
      const vs = Array.from(document.querySelectorAll('video'));
      return vs.find((v) => !v.paused && !v.ended)
        || vs.find((v) => v.readyState > 0 && v.offsetWidth > 0)
        || vs.find((v) => v.readyState > 0)
        || null;
    },
    isPlaying() {
      const v = this.video();
      return !!v && !v.paused && !v.ended;
    },
    enter() {
      const v = this.video();
      if (!v) return 'no-video';
      if (isPiP(v)) return 'already';
      unlock(v);
      if (v.webkitSupportsPresentationMode && v.webkitSupportsPresentationMode('picture-in-picture')) {
        v.webkitSetPresentationMode('picture-in-picture');
        return 'entered';
      }
      if (v.requestPictureInPicture) { v.requestPictureInPicture().catch(() => {}); return 'requested'; }
      return 'unsupported';
    },
    exit() {
      const v = this.video();
      if (v && v.webkitPresentationMode === 'picture-in-picture') v.webkitSetPresentationMode('inline');
      else if (document.pictureInPictureElement) document.exitPictureInPicture().catch(() => {});
      return 'exited';
    },
    toggle() {
      return isPiP(this.video()) ? this.exit() : this.enter();
    },
    // YouTube starts videos muted when it thinks nobody tapped; the official app plays with sound.
    unmute() {
      const p = document.getElementById('movie_player');
      if (p && typeof p.unMute === 'function') p.unMute();
      const v = this.video();
      if (v) v.muted = false;
    },
    unmuteWhenPlaying() {
      this.unmute();
      document.addEventListener('playing', () => this.unmute(), { capture: true, once: true });
      setTimeout(() => this.unmute(), 1500);
    },
    // State for the native mini player (the page stays as it is; the app shrinks the web view).
    playerState() {
      const v = this.video();
      const md = navigator.mediaSession && navigator.mediaSession.metadata;
      return {
        url: location.href,
        title: (md && md.title) || document.title.replace(/ - YouTube$/, ''),
        channel: (md && md.artist) || '',
        time: v ? v.currentTime : 0,
        duration: v && isFinite(v.duration) ? v.duration : 0,
        playing: !!v && !v.paused && !v.ended,
        rect: (() => { if (!v) return null; const r = v.getBoundingClientRect(); return { x: r.left, y: r.top, w: r.width, h: r.height }; })()
      };
    },
    togglePlay() {
      const v = this.video();
      if (!v) return false;
      if (v.paused) v.play().catch(() => {}); else v.pause();
      return !v.paused;
    },
    pauseAll() { document.querySelectorAll('video').forEach((v) => v.pause()); },
    // A watch page whose player loaded but whose title, comments and related videos never did
    // (e.g. iOS paused the app mid-load). The app reloads such pages.
    watchPageIncomplete() {
      if (!location.pathname.startsWith('/watch') || document.readyState !== 'complete') return false;
      if (!document.querySelector('#player-container-id')) return false;
      const results = document.querySelector('ytm-single-column-watch-next-results-renderer');
      return !results || results.getBoundingClientRect().height < 50;
    },
    // Lock Screen / CarPlay / headphone controls, sent from the app.
    remote(command, value) {
      const v = this.video();
      const press = (pattern) => {
        const b = [...document.querySelectorAll('button')].find((e) => pattern.test(e.getAttribute('aria-label') || ''));
        if (b) b.click();
        return !!b;
      };
      switch (command) {
        case 'play': if (v) { v.play().catch(() => {}); this.unmute(); } break;
        case 'pause': if (v) v.pause(); break;
        case 'toggle': this.togglePlay(); break;
        case 'seekBy': if (v) v.currentTime = Math.max(0, Math.min(v.currentTime + value, (v.duration || 1e9) - 0.5)); break;
        case 'seekTo': if (v) v.currentTime = value; break;
        case 'rate': if (v) v.playbackRate = value; break;
        case 'like': return press(/^like this video/i);
        case 'dislike': return press(/^dislike this video/i);
        case 'next': return press(/^next video$/i);
        case 'previous': if (v) v.currentTime = 0; break;
      }
      return true;
    },
    // Called when the app is about to leave the foreground.
    rememberState() {
      this.wasPlaying = this.isPlaying();
      return this.wasPlaying;
    },
    // Called once the app is in the background.
    keepPlaying(autoPiP, backgroundPlay) {
      if (!this.wasPlaying) return 'idle';
      const v = this.video();
      if (!v) return 'no-video';
      if (autoPiP && !isPiP(v)) this.enter();
      if (!backgroundPlay && !isPiP(v)) return 'paused';
      const resume = () => { if (v.paused) v.play().catch(() => {}); };
      resume();
      setTimeout(resume, 400);
      setTimeout(resume, 1200);
      return 'playing';
    }
  };
  window.__youpup = api;

  // Sponsor segments (from SponsorBlock, fetched natively): skip them once each as playback reaches them.
  let sponsor = { id: null, segments: [], skipped: new Set() };
  const labels = { sponsor: 'sponsor', selfpromo: 'self-promotion', interaction: 'subscribe reminder', intro: 'intro',
    outro: 'ending', preview: 'preview', filler: 'filler', music_offtopic: 'non-music part' };
  api.setSegments = (id, segments) => {
    sponsor = { id: id, segments: segments, skipped: new Set() };
    return segments.length;
  };
  const toast = (text) => {
    let el = document.getElementById('youpup-toast');
    if (!el) {
      el = document.createElement('div');
      el.id = 'youpup-toast';
      el.style.cssText = 'position:fixed;left:50%;bottom:calc(env(safe-area-inset-bottom) + 72px);' +
        'transform:translateX(-50%);z-index:9999;padding:10px 16px;border-radius:8px;' +
        'background:rgba(15,15,15,.9);color:#fff;font:500 14px/1.3 Roboto,-apple-system,system-ui;' +
        'pointer-events:none;opacity:0;transition:opacity .25s';
      document.body.appendChild(el);
    }
    el.textContent = text;
    el.style.opacity = '1';
    clearTimeout(el._hide);
    el._hide = setTimeout(() => { el.style.opacity = '0'; }, 2200);
  };
  document.addEventListener('timeupdate', (e) => {
    const v = e.target;
    if (v.tagName !== 'VIDEO' || !sponsor.segments.length) return;
    if (new URLSearchParams(location.search).get('v') !== sponsor.id) return;
    const player = v.closest('.html5-video-player');
    if (player && player.classList.contains('ad-showing')) return;
    const t = v.currentTime;
    for (const s of sponsor.segments) {
      if (t >= s.start && t < s.end - 0.5 && !sponsor.skipped.has(s.start)) {
        sponsor.skipped.add(s.start);  // once: seeking back into it later is the viewer's choice
        v.currentTime = s.end;
        toast('Skipped ' + (labels[s.category] || s.category));
        break;
      }
    }
  }, true);

  // Report the playback position every few seconds (and on pause) so the app can resume
  // there if iOS closes it in the background.
  let lastPositionReport = 0;
  const reportPosition = (v) => {
    const md = navigator.mediaSession && navigator.mediaSession.metadata;
    post({ type: 'position', url: location.href, time: v.currentTime,
           duration: isFinite(v.duration) ? v.duration : 0, playing: !v.paused && !v.ended, rate: v.playbackRate,
           title: (md && md.title) || document.title.replace(/ - YouTube$/, ''), channel: (md && md.artist) || '' });
  };
  document.addEventListener('timeupdate', (e) => {
    if (e.target.tagName !== 'VIDEO' || Date.now() - lastPositionReport < 4000) return;
    lastPositionReport = Date.now();
    reportPosition(e.target);
  }, true);
  // State changes are reported right away so Now Playing (Lock Screen, CarPlay) stays in step.
  for (const type of ['pause', 'playing', 'ratechange', 'seeked', 'loadedmetadata']) {
    document.addEventListener(type, (e) => { if (e.target.tagName === 'VIDEO') reportPosition(e.target); }, true);
  }
  document.addEventListener('ended', (e) => {
    if (e.target.tagName === 'VIDEO') post({ type: 'ended', url: location.href });
  }, true);

  // Picture in Picture button in YouTube's own player controls, next to captions and settings.
  // Built with DOM calls: YouTube's Trusted Types policy rejects innerHTML strings.
  const pipIcon = () => {
    const ns = 'http://www.w3.org/2000/svg';
    const svg = document.createElementNS(ns, 'svg');
    svg.setAttribute('viewBox', '0 0 24 24');
    svg.setAttribute('width', '24');
    svg.setAttribute('height', '24');
    svg.setAttribute('fill', 'currentColor');
    svg.setAttribute('aria-hidden', 'true');
    const path = document.createElementNS(ns, 'path');
    path.setAttribute('d', 'M19 11h-8v6h8v-6zm4 8V4.98C23 3.88 22.1 3 21 3H3c-1.1 0-2 .88-2 1.98V19c0 1.1.9 2 2 2h18c1.1 0 2-.9 2-2zm-2 .02H3V4.97h18v14.05z');
    svg.appendChild(path);
    return svg;
  };
  const addPiPButton = () => {
    const bar = document.querySelector('.player-controls-top');
    if (!bar || bar.querySelector('.youpup-pip-button')) return;
    const button = document.createElement('button');
    button.className = 'icon-button youpup-pip-button';
    button.setAttribute('aria-label', 'Picture in Picture');
    button.appendChild(pipIcon());
    button.addEventListener('click', (e) => { e.stopPropagation(); api.toggle(); }, true);
    bar.insertBefore(button, bar.firstChild);
  };

  // YouTube builds and tears down the control bar as the controls show and hide,
  // so watch the player (not the whole page) and add the button whenever the bar appears.
  const watchedPlayers = new WeakSet();
  const controlsObserver = new MutationObserver(addPiPButton);
  const watchPlayer = (video) => {
    // The outer container: the controls are siblings of the video element's own player box.
    const player = video.closest('#player-container-id') || video.closest('.player-container') || document.querySelector('ytm-app') || document.body;
    if (!player || watchedPlayers.has(player)) return;
    watchedPlayers.add(player);
    controlsObserver.observe(player, { childList: true, subtree: true });
  };
  for (const type of ['play', 'loadedmetadata']) {
    document.addEventListener(type, (e) => {
      if (e.target.tagName !== 'VIDEO') return;
      unlock(e.target);
      watchPlayer(e.target);
      addPiPButton();
    }, true);
  }
  // Preferred quality: YouTube's site picks a low quality (often 360p) in apps like this one.
  // Applied once per video; the app updates prefs.quality when the network changes.
  let qualityAppliedFor = null;
  // Audio-only (set by the app while nothing shows the video): the smallest video stream. YouTube keeps
  // the same audio stream at every video quality, so the sound doesn't change.
  let audioOnly = false, wasAudioOnly = false;
  const applyQuality = () => {
    const player = document.getElementById('movie_player');
    const id = new URLSearchParams(location.search).get('v');
    const quality = audioOnly ? 'tiny' : prefs.quality;
    if (!player || typeof player.getAvailableQualityLevels !== 'function') return;
    if (player.classList.contains('ad-showing')) return;
    if (!quality) {
      // Back from audio-only with no preferred quality: let YouTube choose again.
      if (wasAudioOnly && typeof player.setPlaybackQualityRange === 'function') player.setPlaybackQualityRange('auto', 'auto');
      wasAudioOnly = false;
      return;
    }
    const levels = player.getAvailableQualityLevels().filter((l) => l !== 'auto');
    if (!levels.length || qualityAppliedFor === id + quality) return;
    // Levels are listed best first; take the wanted one, or the best one below it.
    const order = ['hd2160', 'hd1440', 'hd1080', 'hd720', 'large', 'medium', 'small', 'tiny'];
    const wanted = quality === 'best' ? levels[0] : quality;
    const target = levels.find((l) => order.indexOf(l) >= order.indexOf(wanted)) || levels[levels.length - 1];
    if (typeof player.setPlaybackQualityRange === 'function') player.setPlaybackQualityRange(target, target);
    else if (typeof player.setPlaybackQuality === 'function') player.setPlaybackQuality(target);
    qualityAppliedFor = id + quality;
    wasAudioOnly = audioOnly;
  };
  api.setQuality = (quality) => { prefs.quality = quality; qualityAppliedFor = null; applyQuality(); };
  // Not while Picture in Picture shows the video.
  api.setAudioOnly = (on) => {
    const next = !!on && !isPiP(api.video());
    if (next !== audioOnly) { audioOnly = next; qualityAppliedFor = null; applyQuality(); }
    return audioOnly;
  };
  const pipChanged = () => { if (audioOnly && isPiP(api.video())) api.setAudioOnly(false); };
  document.addEventListener('enterpictureinpicture', pipChanged, true);
  document.addEventListener('webkitpresentationmodechanged', pipChanged, true);

  // Remember the playback speed you pick and use it for the next videos.
  const SPEED_KEY = 'youpup-speed';
  let applyingSpeed = false;
  document.addEventListener('ratechange', (e) => {
    const v = e.target;
    if (!prefs.rememberSpeed || v.tagName !== 'VIDEO' || applyingSpeed) return;
    const player = v.closest('.html5-video-player');
    if ((player && player.classList.contains('ad-showing')) || v.playbackRate > 4) return;  // ad fast-forward
    try { localStorage.setItem(SPEED_KEY, String(v.playbackRate)); } catch (err) {}
  }, true);
  const applySpeed = (v) => {
    if (!prefs.rememberSpeed) return;
    let speed = 1;
    try { speed = parseFloat(localStorage.getItem(SPEED_KEY)) || 1; } catch (err) {}
    const player = v.closest('.html5-video-player');
    if (speed === 1 || v.playbackRate === speed || (player && player.classList.contains('ad-showing'))) return;
    applyingSpeed = true;
    if (player && typeof player.setPlaybackRate === 'function') player.setPlaybackRate(speed); else v.playbackRate = speed;
    setTimeout(() => { applyingSpeed = false; }, 0);
  };
  for (const type of ['playing', 'loadedmetadata']) {
    document.addEventListener(type, (e) => {
      if (e.target.tagName !== 'VIDEO' || !e.target.closest('#player-container-id')) return;
      applyQuality();
      applySpeed(e.target);
    }, true);
  }

  // Dislike counts (from Return YouTube Dislike, fetched by the app) next to YouTube's dislike icon.
  let dislikes = { id: null, text: '' };
  const showDislikes = () => {
    if (new URLSearchParams(location.search).get('v') !== dislikes.id) return;
    const button = [...document.querySelectorAll('button')]
      .find((b) => /^dislike/i.test(b.getAttribute('aria-label') || ''));
    if (!button) return;
    let label = button.querySelector('.youpup-dislikes');
    if (!label) {
      label = document.createElement('span');
      label.className = 'youpup-dislikes';
      button.appendChild(label);
    }
    if (label.textContent !== dislikes.text) label.textContent = dislikes.text;
  };
  const shortCount = (n) => n >= 1e9 ? (n / 1e9).toFixed(n < 1e10 ? 1 : 0).replace(/\.0$/, '') + 'B'
    : n >= 1e6 ? (n / 1e6).toFixed(n < 1e7 ? 1 : 0).replace(/\.0$/, '') + 'M'
    : n >= 1e3 ? (n / 1e3).toFixed(n < 1e4 ? 1 : 0).replace(/\.0$/, '') + 'K' : String(n);
  api.setDislikes = (id, count) => {
    dislikes = { id, text: shortCount(count) };
    // YouTube re-renders the action bar a few times while the page settles.
    for (const delay of [0, 400, 1200, 3000]) setTimeout(showDislikes, delay);
  };

  document.addEventListener('webkitpresentationmodechanged', (e) => {
    post({ type: 'pip', active: e.target.webkitPresentationMode === 'picture-in-picture' });
  }, true);
  document.addEventListener('enterpictureinpicture', () => post({ type: 'pip', active: true }), true);
  document.addEventListener('leavepictureinpicture', () => post({ type: 'pip', active: false }), true);

  // Report the page and top-bar colors so the status bar and home-indicator areas match.
  // The watch page's "ambient" top bar is painted, not styled, so it's special-cased.
  const bg = (el) => (el ? getComputedStyle(el).backgroundColor : '');
  const transparent = (c) => !c || c === 'transparent' || /,\s*0\)$/.test(c);
  let lastColors = '';
  let scheduled = false;
  let observedApp = null;
  const reportColors = () => {
    scheduled = false;
    const html = document.documentElement;
    if (!html) return;
    let page = bg(html);
    if (transparent(page)) page = bg(document.body);
    const app = document.querySelector('ytm-app');
    if (app && app !== observedApp) { observedApp = app; watchAttributes(app); }
    const onWatch = !!document.querySelector('ytm-watch.ambient-topbar') && !!app && app.classList.contains('sticky-player');
    // Shorts play full screen behind the status bar, so its text should be light.
    const onShorts = location.pathname.startsWith('/shorts');
    const top = onShorts ? 'rgb(0, 0, 0)' : onWatch ? 'rgb(18, 18, 18)' : page;
    const key = top + '|' + page;
    if (key === lastColors) return;
    lastColors = key;
    post({ type: 'colors', top: top, page: page });
  };
  // Full screen like the official app. iPhone web views have no Fullscreen API, so YouTube falls back
  // to Apple's plain player. Provide the API: the requested element fills the screen (CSS below) and the
  // app rotates to landscape, so YouTube shows its own full-screen player UI.
  let fullscreenElement = null;
  const setFullscreen = (el) => {
    if (el === fullscreenElement) return;
    const previous = fullscreenElement;
    fullscreenElement = el;
    if (previous) previous.classList.remove('youpup-fullscreen');
    if (el) el.classList.add('youpup-fullscreen');
    document.documentElement.classList.toggle('youpup-fs', !!el);
    post({ type: 'fullscreen', active: !!el });
    for (const type of ['fullscreenchange', 'webkitfullscreenchange']) {
      (el || previous || document).dispatchEvent(new Event(type, { bubbles: true }));
    }
    for (const delay of [50, 350, 800]) setTimeout(() => window.dispatchEvent(new Event('resize')), delay);
  };
  try {
    const getter = (name, get) => Object.defineProperty(Document.prototype, name, { get, configurable: true });
    getter('fullscreenEnabled', () => true);
    getter('webkitFullscreenEnabled', () => true);
    getter('fullscreenElement', () => fullscreenElement);
    getter('webkitFullscreenElement', () => fullscreenElement);
    getter('webkitCurrentFullScreenElement', () => fullscreenElement);
    getter('webkitIsFullScreen', () => !!fullscreenElement);
    Element.prototype.requestFullscreen = function () { setFullscreen(this); return Promise.resolve(); };
    Element.prototype.webkitRequestFullscreen = function () { setFullscreen(this); };
    Element.prototype.webkitRequestFullScreen = Element.prototype.webkitRequestFullscreen;
    Document.prototype.exitFullscreen = function () { setFullscreen(null); return Promise.resolve(); };
    Document.prototype.webkitExitFullscreen = function () { setFullscreen(null); };
    Document.prototype.webkitCancelFullScreen = Document.prototype.webkitExitFullscreen;
    // YouTube's iPhone path: send Apple's native video full screen to its own player instead.
    HTMLVideoElement.prototype.webkitEnterFullscreen = function () {
      setFullscreen(this.closest('.html5-video-player') || this);
    };
  } catch (e) {}

  const player = () => document.getElementById('movie_player');
  const enterFullscreen = () => {
    const p = player();
    if (!p || fullscreenElement) return;
    if (typeof p.toggleFullscreen === 'function') p.toggleFullscreen(); else p.requestFullscreen();
  };
  const exitFullscreen = () => {
    if (!fullscreenElement) return;
    const p = player();
    if (p && typeof p.toggleFullscreen === 'function') p.toggleFullscreen(); else setFullscreen(null);
    if (fullscreenElement) setFullscreen(null);
  };
  api.exitFullscreen = exitFullscreen;
  api.enterFullscreen = () => { if (location.pathname.startsWith('/watch')) enterFullscreen(); };

  // Official-app player gestures (hold for 2x speed is YouTube's own and already works):
  //   swipe down in full screen → leave · swipe up on the player → full screen
  //   double-tap left/right → back/forward 10 s (taps add up) · pinch in full screen → zoom to fill
  const playerBox = () => document.getElementById('player-container-id');
  const onControl = (target) => !!target.closest('button, a, input, [role="slider"], [role="button"], ' +
    '.ytProgressBarLineHost, .ytwPlayerProgressBarHost, .progress-bar-line, .fullscreen-action-menu, ' +
    'ytm-fullscreen-related-videos-entry-point-view-model, .ytFullscreenVideoRecommendationsHost');
  const makeEl = (tag, css, text) => {
    const el = document.createElement(tag);
    el.style.cssText = css;
    if (text) el.textContent = text;
    return el;
  };
  const flash = (() => {
    let el;
    return (text) => {
      const box = playerBox();
      if (!box) return;
      if (!el || !box.contains(el)) {
        el = makeEl('div', 'position:absolute;left:50%;top:18%;transform:translateX(-50%);z-index:60;' +
          'padding:8px 14px;border-radius:18px;background:rgba(0,0,0,.6);color:#fff;' +
          'font:500 14px/1.2 Roboto,-apple-system,system-ui;pointer-events:none;opacity:0;transition:opacity .2s');
        box.appendChild(el);
      }
      el.textContent = text;
      el.style.opacity = '1';
      clearTimeout(el._hide);
      el._hide = setTimeout(() => { el.style.opacity = '0'; }, 1100);
    };
  })();

  // Double-tap seeking with a ripple on the tapped side, like the official app.
  let seekSide = 0, seekTotal = 0, seekTimer = null, lastTap = null, seekBubble = null;
  const showSeek = (side, seconds) => {
    const box = playerBox();
    if (!box) return;
    if (!seekBubble || !box.contains(seekBubble)) {
      seekBubble = makeEl('div', 'position:absolute;top:0;bottom:0;width:40%;z-index:55;display:flex;' +
        'align-items:center;justify-content:center;pointer-events:none;background:rgba(255,255,255,.12);' +
        'color:#fff;font:500 14px/1.3 Roboto,-apple-system,system-ui;text-align:center;opacity:0;transition:opacity .25s');
      box.appendChild(seekBubble);
    }
    seekBubble.style.left = side < 0 ? '0' : 'auto';
    seekBubble.style.right = side > 0 ? '0' : 'auto';
    seekBubble.style.borderRadius = side < 0 ? '0 50% 50% 0 / 0 50% 50% 0' : '50% 0 0 50% / 50% 0 0 50%';
    seekBubble.textContent = (side < 0 ? '◀◀  ' : '') + seconds + ' seconds' + (side > 0 ? '  ▶▶' : '');
    seekBubble.style.opacity = '1';
    clearTimeout(seekBubble._hide);
    seekBubble._hide = setTimeout(() => { seekBubble.style.opacity = '0'; }, 700);
  };
  const seekBy = (side) => {
    const v = document.querySelector('#player-container-id video');
    if (!v) return;
    if (side !== seekSide) seekTotal = 0;
    seekSide = side;
    seekTotal += 10;
    const end = isFinite(v.duration) ? v.duration - 0.25 : Infinity;
    v.currentTime = Math.max(0, Math.min(end, v.currentTime + side * 10));
    showSeek(side, seekTotal);
    clearTimeout(seekTimer);
    seekTimer = setTimeout(() => { seekSide = 0; seekTotal = 0; }, 900);
  };

  let gesture = null;
  document.addEventListener('touchstart', (e) => {
    const box = playerBox();
    if (!box || !location.pathname.startsWith('/watch') || !box.contains(e.target)) { gesture = null; return; }
    if (e.touches.length === 2) {
      const [a, b] = e.touches;
      gesture = { pinch: Math.hypot(a.clientX - b.clientX, a.clientY - b.clientY) };
      return;
    }
    const t = e.touches[0];
    gesture = { x: t.clientX, y: t.clientY, time: Date.now(), control: onControl(e.target), multi: false };
  }, { capture: true, passive: true });

  document.addEventListener('touchmove', (e) => {
    if (gesture && e.touches.length > 1 && !gesture.pinch) gesture.multi = true;
    if (gesture && gesture.pinch && e.touches.length === 2) {
      const [a, b] = e.touches;
      gesture.pinchEnd = Math.hypot(a.clientX - b.clientX, a.clientY - b.clientY);
    }
  }, { capture: true, passive: true });

  document.addEventListener('touchend', (e) => {
    const g = gesture;
    if (!g) return;
    if (g.pinch) {
      if (e.touches.length === 0) gesture = null;
      if (!fullscreenElement || !g.pinchEnd) return;
      const ratio = g.pinchEnd / g.pinch;
      const html = document.documentElement;
      if (ratio > 1.15 && !html.classList.contains('youpup-fill')) { html.classList.add('youpup-fill'); flash('Zoomed to fill'); }
      else if (ratio < 0.87 && html.classList.contains('youpup-fill')) { html.classList.remove('youpup-fill'); flash('Original'); }
      return;
    }
    gesture = null;
    if (g.multi) return;
    const t = e.changedTouches[0];
    const dx = t.clientX - g.x, dy = t.clientY - g.y, dt = Date.now() - g.time;
    // A swipe down over the "More videos" cards closes that panel (a drag never opens a card).
    const relatedOpen = fullscreenElement && document.querySelector('.fullscreen-controls.expanded');
    const swipeDown = Math.abs(dy) > 60 && Math.abs(dy) > Math.abs(dx) * 1.5 && dt < 700 && dy > 0;
    if (g.control && !(relatedOpen && swipeDown)) return;
    const vertical = Math.abs(dy) > 60 && Math.abs(dy) > Math.abs(dx) * 1.5 && dt < 700;
    if (vertical && dy > 0 && fullscreenElement) {
      lastTap = null;
      // With "More videos" open, swipe down closes that panel first (like the official app).
      if (document.querySelector('.fullscreen-controls.expanded')) {
        api.lastGesture = 'closeRelated';
        // YouTube handles the same touch right after this and would reopen the panel,
        // so close it once YouTube is done.
        setTimeout(() => {
          if (!document.querySelector('.fullscreen-controls.expanded')) return;
          const close = document.querySelector('player-fullscreen-controls button[aria-label="Close"]')
            || document.querySelector('.ytwPlayerFullscreenTopControlsFullscreenCloseButtonWrapper button');
          if (close) close.click();
        }, 300);
        return;
      }
      api.lastGesture = 'exit';
      exitFullscreen();
      return;
    }
    if (vertical && dy < 0 && !fullscreenElement) { lastTap = null; enterFullscreen(); return; }
    if (vertical && dy < 0 && fullscreenElement) {
      // Swipe up in full screen opens the related videos panel ("More videos").
      lastTap = null;
      api.lastGesture = 'related';
      // The entry point only reacts once the controls are showing (the touch just revealed them).
      const openRelated = () => {
        const more = document.querySelector('ytm-fullscreen-related-videos-entry-point-view-model button');
        if (more) more.click();
      };
      setTimeout(openRelated, 250);
      return;
    }
    if (vertical && dy > 0 && !fullscreenElement) {
      // Swipe down in portrait shrinks the video into the app's mini player.
      lastTap = null;
      const v = document.querySelector('#player-container-id video');
      const box = v ? v.getBoundingClientRect() : playerBox().getBoundingClientRect();
      post({ type: 'minimize', url: location.href, time: v ? v.currentTime : 0,
             rect: { x: box.left, y: box.top, w: box.width, h: box.height } });
      return;
    }
    // Taps: a second quick tap on the left or right third seeks.
    if (Math.abs(dx) > 12 || Math.abs(dy) > 12 || dt > 300) { lastTap = null; return; }
    const r = playerBox().getBoundingClientRect();
    const rel = (t.clientX - r.left) / r.width;
    const side = rel < 1 / 3 ? -1 : rel > 2 / 3 ? 1 : 0;
    const now = Date.now();
    if (side && (seekSide === side || (lastTap && now - lastTap.time < 320 && lastTap.side === side))) {
      seekBy(side);
      lastTap = null;
    } else {
      lastTap = { time: now, side };
    }
  }, { capture: true, passive: true });
  // Turning the phone (rotation lock off): landscape on a video enters full screen, portrait leaves it.
  matchMedia('(orientation: landscape)').addEventListener('change', (e) => {
    if (e.matches && location.pathname.startsWith('/watch')) enterFullscreen();
    else if (!e.matches) exitFullscreen();
  });
  // Leaving the video page leaves full screen.
  const leaveOnNavigation = () => { if (fullscreenElement && !document.contains(fullscreenElement)) setFullscreen(null); };

  // The app asks again when this page comes back on screen (mini player → full size).
  api.refreshColors = () => { lastColors = ''; reportColors(); };

  // Event-driven (no polling): re-check after navigations, theme changes and layout class changes.
  const schedule = () => {
    if (!scheduled) { scheduled = true; setTimeout(() => { reportColors(); leaveOnNavigation(); }, 50); }
  };
  const attributeObserver = new MutationObserver(schedule);
  const watchAttributes = (el) => attributeObserver.observe(el, { attributes: true, attributeFilter: ['class', 'dark', 'style'] });
  watchAttributes(document.documentElement);
  for (const method of ['pushState', 'replaceState']) {
    const original = history[method];
    history[method] = function () {
      const result = original.apply(this, arguments);
      schedule();
      setTimeout(schedule, 700);  // the new page renders a moment after the URL changes
      return result;
    };
  }
  window.addEventListener('popstate', schedule);
  window.addEventListener('pageshow', schedule);
  window.addEventListener('load', schedule);
  document.addEventListener('DOMContentLoaded', schedule);
  matchMedia('(prefers-color-scheme: dark)').addEventListener('change', schedule);
})();

